# -*- coding: utf-8 -*-# Avbebe 爬虫源 - 适配 TVBox / CatVod# 仅个人学习使用import sysimport reimport jsonimport htmlimport base64import requestsfrom urllib.parse import quote, unquote, urljoinfrom lxml import etreesys.path.append('..')from base.spider import Spider as BaseSpiderclass Spider(BaseSpider):    def __init__(self):        super().__init__()        self.host = "https://avbebe.com"        self.headers = {            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8",            "Accept-Language": "zh-CN,zh;q=0.9",            "Referer": self.host + "/",        }        self.session = requests.Session()        self.session.headers.update(self.headers)        self.categories = [            {"type_id": "new", "type_name": "新番"},            {"type_id": "h%e5%8b%95%e7%95%ab%e5%bd%b1%e7%89%87", "type_name": "動畫卡通"},            {"type_id": "3d%e5%8b%95%e7%95%ab", "type_name": "3D動畫"},            {"type_id": "%e6%b3%a1%e9%ba%b5%e7%95%aa", "type_name": "泡麵番"},            {"type_id": "%e6%88%90%e4%ba%bah%e6%bc%ab%e7%95%ab", "type_name": "綜合漫畫"},            {"type_id": "%e9%ab%98%e6%b8%85%e4%b8%ad%e5%ad%97", "type_name": "高清中字"},            {"type_id": "%e9%ab%98%e6%b8%85%e7%b4%a0%e4%ba%ba", "type_name": "高清素人"},            {"type_id": "%e9%a6%ac%e8%b3%bd%e5%85%8b%e7%a0%b4%e8%a7%a3", "type_name": "馬賽克破解"},            {"type_id": "%e8%8f%af%e8%aa%9eav", "type_name": "華語AV"},            {"type_id": "%e7%b6%9c%e5%90%88av", "type_name": "綜合AV"},        ]        self._seen_ids = set()    def init(self, extend=""):        pass    def getName(self):        return "Avbebe"    def isVideoFormat(self, url):        return any(x in url for x in [".m3u8", ".mp4", ".flv", ".webm", ".ts"])    def manualVideoCheck(self):        return False    def _fix_url(self, url):        if not url:            return ""        if url.startswith(("data:", "javascript:", "blob:", "file:")):            return ""        if url.startswith("//"):            return "https:" + url        if url.startswith("/"):            return urljoin(self.host, url)        if url.startswith("http"):            return url        return urljoin(self.host, "/" + url)    def _clean_text(self, text):        if not text:            return ""        return html.unescape(re.sub(r"<[^>]+>", "", text)).strip()    def _fetch(self, url):        try:            r = self.session.get(url, timeout=15)            r.encoding = "utf-8"            return r.text        except Exception:            return ""    def _parse_html(self, html_text):        if not html_text:            return None        try:            return etree.HTML(html_text)        except Exception:            return None    def _extract_bg_url(self, element):        bg = element.get("data-bg") if element is not None else ""        if bg:            m = re.search(r"url\(['\"]?([^'\"()]+)['\"]?\)", bg)            if m:                return m.group(1)            elif bg.startswith("http"):                return bg        return ""    def homeContent(self, filter):        return {"class": self.categories, "filters": {}}    def homeVideoContent(self):        return self.categoryContent("new", "1", False, {})    def categoryContent(self, tid, pg, filter, extend):        try:            pg = int(pg) if pg else 1            url = f"{self.host}/archives/category/{tid}/page/{pg}/"            html_text = self._fetch(url)            if not html_text:                return {"list": [], "page": pg, "pagecount": 1, "limit": 24, "total": 0}            doc = self._parse_html(html_text)            if doc is None:                return {"list": [], "page": pg, "pagecount": 1, "limit": 24, "total": 0}            items = []            slides = doc.xpath("//div[contains(@class,'swiper-slide')]")            if not slides:                slides = doc.xpath("//article | //div[contains(@class,'post')]")            if not slides:                slides = doc.xpath("//a[contains(@href,'/archives/') and .//img]")            for slide in slides:                try:                    if slide.tag == "a":                        link = slide.get("href")                        container = slide                    else:                        link_node = slide.xpath(".//a[contains(@href,'/archives/')]")                        if link_node:                            link = link_node[0].get("href")                            container = link_node[0]                        else:                            continue                    if not link:                        continue                    pic = ""                    bg_div = slide.xpath(".//div[contains(@class,'elementor-cta__bg')]")                    if bg_div:                        pic = self._extract_bg_url(bg_div[0])                    if not pic:                        img_node = slide.xpath(".//img")                        if img_node:                            pic = img_node[0].get("src") or img_node[0].get("data-src") or img_node[0].get("data-original") or ""                    if not pic:                        style = slide.get("style") if slide.tag != "a" else ""                        if style:                            m = re.search(r"url\(([^)]+)\)", style)                            if m:                                pic = m.group(1).strip("'\"")                    pic = self._fix_url(pic)                    title = ""                    title_span = slide.xpath(".//span[contains(@class,'elementor-cta__title')]")                    if title_span:                        title = self._clean_text("".join(title_span[0].xpath(".//text()")))                    if not title:                        title_node = slide.xpath(".//h3 | .//h2 | .//h4 | .//img/@alt")                        if title_node:                            if isinstance(title_node[0], str):                                title = title_node[0]                            else:                                title = self._clean_text("".join(title_node[0].xpath(".//text()")))                    if not title:                        title = link.split("/")[-2] or "未知"                    vid_match = re.search(r"/archives/(\d+)", link)                    vid = vid_match.group(1) if vid_match else link                    if vid in self._seen_ids:                        continue                    self._seen_ids.add(vid)                    items.append({                        "vod_id": vid,                        "vod_name": self._clean_text(title),                        "vod_pic": pic,                        "vod_remarks": "",                    })                except Exception:                    continue            pagecount = pg + 1            total = len(items) * pagecount            return {"list": items, "page": pg, "pagecount": pagecount, "limit": 24, "total": total}        except Exception as e:            print(f"[Avbebe] categoryContent error: {e}")            return {"list": [], "page": int(pg) if pg else 1, "pagecount": 1, "limit": 24, "total": 0}    def detailContent(self, ids):        try:            vid = str(ids[0]) if ids else ""            if not vid:                return {"list": []}            url = f"{self.host}/archives/{vid}/"            html_text = self._fetch(url)            if not html_text:                url = f"{self.host}/archives/{vid}"                html_text = self._fetch(url)            if not html_text:                return {"list": []}            doc = self._parse_html(html_text)            if doc is None:                return {"list": []}            # 标题            title_node = doc.xpath("//h1[contains(@class,'entry-title')] | //h1[contains(@class,'jeg_post_title')] | //h1")            title = self._clean_text("".join(title_node[0].xpath(".//text()"))) if title_node else "未知"            # 封面图            pic = ""            meta_og = doc.xpath("//meta[@property='og:image']/@content")            if meta_og:                pic = meta_og[0]            if not pic:                img_node = doc.xpath("//img[contains(@class,'wp-post-image') or contains(@class,'attachment-')]")                if img_node:                    pic = img_node[0].get("src") or img_node[0].get("data-src") or ""            if not pic:                first_img = doc.xpath("//article//img[1]/@src")                if first_img:                    pic = first_img[0]            pic = self._fix_url(pic)            # 播放地址提取（重点修复）            play_url = ""            # 1. 解析 flowplayer 的 data-item 属性（包含 m3u8 源）            fp_divs = doc.xpath("//div[contains(@class,'flowplayer') and @data-item]")            if fp_divs:                try:                    data_item = fp_divs[0].get("data-item")                    if data_item:                        item_data = json.loads(data_item)                        sources = item_data.get("sources", [])                        if sources and sources[0].get("src"):                            play_url = self._fix_url(sources[0]["src"])                except Exception:                    pass            # 2. 如果没找到，尝试从 iframe 获取（备用源）            if not play_url:                iframe_src = doc.xpath("//iframe/@src")                for ifs in iframe_src:                    if "youtube" in ifs or "vimeo" in ifs or "dailymotion" in ifs or "player" in ifs:                        play_url = ifs                        break            # 3. 直接匹配 m3u8/mp4 链接            if not play_url:                m3u8_matches = re.findall(r'(https?://[^\s"\'<>]+\.(?:m3u8|mp4|flv|webm))', html_text)                if m3u8_matches:                    play_url = m3u8_matches[0]            # 4. JS 变量            if not play_url:                js_patterns = [                    r'file\s*[:=]\s*["\']([^"\']+\.(?:m3u8|mp4))',                    r'url\s*[:=]\s*["\']([^"\']+\.(?:m3u8|mp4))',                    r'src\s*[:=]\s*["\']([^"\']+\.(?:m3u8|mp4))',                    r'video\s*[:=]\s*["\']([^"\']+\.(?:m3u8|mp4))',                ]                for pat in js_patterns:                    m = re.search(pat, html_text, re.I)                    if m:                        play_url = self._fix_url(m.group(1))                        break            # 5. video 标签            if not play_url:                video_src = doc.xpath("//video/@src | //video//source/@src")                if video_src:                    play_url = self._fix_url(video_src[0])            if play_url:                play_url = f"正片${play_url}"            else:                play_url = ""            vod = {                "vod_id": vid,                "vod_name": title,                "vod_pic": pic,                "vod_play_from": "默认线路",                "vod_play_url": play_url,                "vod_content": "",            }            return {"list": [vod]}        except Exception as e:            print(f"[Avbebe] detailContent error: {e}")            return {"list": []}    def playerContent(self, flag, id, vipFlags=None):        try:            if self.isVideoFormat(id):                return {"parse": 0, "url": id, "header": self.headers}            if id.startswith(self.host):                html_text = self._fetch(id)                if html_text:                    # 同样尝试解析 data-item                    doc = self._parse_html(html_text)                    if doc is not None:                        fp_divs = doc.xpath("//div[contains(@class,'flowplayer') and @data-item]")                        if fp_divs:                            try:                                data_item = fp_divs[0].get("data-item")                                if data_item:                                    item_data = json.loads(data_item)                                    sources = item_data.get("sources", [])                                    if sources and sources[0].get("src"):                                        return {"parse": 0, "url": self._fix_url(sources[0]["src"]), "header": self.headers}                            except Exception:                                pass                    # 降级：正则                    m3u8 = re.search(r'(https?://[^\s"\'<>]+\.(?:m3u8|mp4|flv|webm))', html_text)                    if m3u8:                        return {"parse": 0, "url": m3u8.group(1), "header": self.headers}            return {"parse": 0, "url": id, "header": self.headers}        except Exception:            return {"parse": 0, "url": id, "header": {}}    def searchContent(self, key, quick, pg="1"):        try:            pg = int(pg) if pg else 1            url = f"{self.host}/?s={quote(key)}&page={pg}"            html_text = self._fetch(url)            if not html_text:                return {"list": [], "page": pg, "pagecount": 1, "limit": 24, "total": 0}            doc = self._parse_html(html_text)            if doc is None:                return {"list": [], "page": pg, "pagecount": 1, "limit": 24, "total": 0}            items = []            articles = doc.xpath("//article | //div[contains(@class,'post')] | //a[contains(@href,'/archives/') and .//img]")            for article in articles:                try:                    if article.tag == "a":                        link = article.get("href")                        container = article                    else:                        link_node = article.xpath(".//a[contains(@href,'/archives/')]")                        if link_node:                            link = link_node[0].get("href")                            container = link_node[0]                        else:                            continue                    if not link:                        continue                    pic = ""                    bg_div = article.xpath(".//div[contains(@class,'elementor-cta__bg')]")                    if bg_div:                        pic = self._extract_bg_url(bg_div[0])                    if not pic:                        img_node = article.xpath(".//img")                        if img_node:                            pic = img_node[0].get("src") or img_node[0].get("data-src") or ""                    pic = self._fix_url(pic)                    title = ""                    title_span = article.xpath(".//span[contains(@class,'elementor-cta__title')]")                    if title_span:                        title = self._clean_text("".join(title_span[0].xpath(".//text()")))                    if not title:                        title_node = article.xpath(".//h3 | .//h2 | .//h4 | .//img/@alt")                        if title_node:                            if isinstance(title_node[0], str):                                title = title_node[0]                            else:                                title = self._clean_text("".join(title_node[0].xpath(".//text()")))                    if not title:                        title = link.split("/")[-2] or "未知"                    vid_match = re.search(r"/archives/(\d+)", link)                    vid = vid_match.group(1) if vid_match else link                    items.append({                        "vod_id": vid,                        "vod_name": self._clean_text(title),                        "vod_pic": pic,                    })                except Exception:                    continue            return {"list": items, "page": pg, "pagecount": pg + 1, "limit": 24, "total": len(items) * (pg + 1)}        except Exception:            return {"list": [], "page": int(pg) if pg else 1, "pagecount": 1, "limit": 24, "total": 0}    def localProxy(self, param):        url = unquote(param.get("url", ""))        if not url or not url.startswith("http"):            return [404, "text/plain", b""]        try:            r = requests.get(url, headers={"Referer": self.host + "/", "User-Agent": self.headers["User-Agent"]}, timeout=15)            return [200, r.headers.get("Content-Type", "image/jpeg"), r.content]        except Exception:            return [404, "text/plain", b""]